import ctypes
import os

# Load the libraries
ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

# Define the function prototype
# double gsl_cdf_tdist_Pinv(const double P, const double nu);
gsl.gsl_cdf_tdist_Pinv.argtypes = [ctypes.c_double, ctypes.c_double]
gsl.gsl_cdf_tdist_Pinv.restype = ctypes.c_double

def inverse_cdf_tdist(P, nu):
    """Compute the inverse CDF for the Student's t-distribution."""
    if not (0 <= P <= 1):
        raise ValueError("Probability P must be between 0 and 1.")
    if nu <= 0:
        raise ValueError("Degrees of freedom nu must be positive.")
    return gsl.gsl_cdf_tdist_Pinv(P, nu)

def assert_test():
    """Test cases for inverse_cdf_tdist function."""
    # Test edge cases
    assert inverse_cdf_tdist(1.0, 1.0) == float('inf'), "Failed on P=1, nu=1"
    assert inverse_cdf_tdist(0.0, 1.0) == float('-inf'), "Failed on P=0, nu=1"
    assert inverse_cdf_tdist(0.5, 1.0) == 0.0, "Failed on P=0.5, nu=1"

    # Test known values
    assert abs(inverse_cdf_tdist(0.975, 10) - 2.228) < 0.001, "Failed on P=0.975, nu=10"
    assert abs(inverse_cdf_tdist(0.025, 10) + 2.228) < 0.001, "Failed on P=0.025, nu=10"

    # Test robustness
    try:
        inverse_cdf_tdist(-0.1, 10)
    except ValueError:
        pass
    else:
        assert False, "Failed to handle P < 0"

    try:
        inverse_cdf_tdist(1.1, 10)
    except ValueError:
        pass
    else:
        assert False, "Failed to handle P > 1"

    try:
        inverse_cdf_tdist(0.5, -1)
    except ValueError:
        pass
    else:
        assert False, "Failed to handle nu <= 0"

if __name__ == "__main__":
    assert_test()
